css:
.profile {
  width: 260px;
  border: 1px solid #ddd;
  border-radius: 12px;
  overflow: {{hidden}};
  text-align: center;
  font-family: sans-serif;
}
.banner {
  height: 60px;
  background: {{linear-gradient(90deg, #f97316, #fbbf24)}};
}
.avatar {
  width: 56px;
  height: 56px;
  margin: -28px auto 0;
  border-radius: {{50%}};
  background: white;
  font-size: 2rem;
  line-height: 56px;
}
.handle { color: {{#888}}; margin: 0; }
.follow {
  margin: 8px 0 14px;
  border: none;
  border-radius: 999px;
  background: #f97316;
  color: white;
  padding: 6px 18px;
  cursor: pointer;
}

.watch { width: 320px; font-family: sans-serif; }
.player {
  aspect-ratio: {{16 / 9}};
  display: flex;
  align-items: center;
  justify-content: {{center}};
  background: #111;
  color: white;
  font-size: 2rem;
  border-radius: 10px;
}
.video-title { font-size: 1.1rem; margin: 10px 0 6px; }
.channel {
  display: {{flex}};
  align-items: center;
  gap: 8px;
  color: #666;
}
.dot {
  width: 28px;
  height: 28px;
  border-radius: {{50%}};
  background: #f97316;
}

.comments {
  width: 300px;
  font-family: {{sans-serif}};
}
.comment {
  border-top: 1px solid #eee;
  padding: 8px 0;
}
.who { font-weight: {{600}}; }
.comment p { margin: 4px 0 0; color: #444; }

.post {
  max-width: {{40ch}};
  margin: 0 auto;
  font-family: Georgia, serif;
  line-height: {{1.6}};
  color: #222;
}
.post-title { font-size: 1.6rem; margin-bottom: 4px; }
.byline {
  color: {{#999}};
  font-style: italic;
  margin-top: 0;
}
